import React, { useState } from 'react';

// ── Seeded RNG ────────────────────────────────────────────────────
function seededRng(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 0xFFFFFFFF; };
}

// ── Colour helpers ────────────────────────────────────────────────
function darken(hex, amt = 0.35) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*(1-amt))},${Math.round(g*(1-amt))},${Math.round(b*(1-amt))})`;
}
function lighten(hex, amt = 0.55) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.min(255,Math.round(r+(255-r)*amt))},${Math.min(255,Math.round(g+(255-g)*amt))},${Math.min(255,Math.round(b+(255-b)*amt))})`;
}
function toVeryDark(hex) {
  // near-black but retains colour hue — for Neuromancer bg
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*0.12+4)},${Math.round(g*0.14+4)},${Math.round(b*0.10+4)})`;
}

// ── Classify book — Neuromancer vs Loeb ───────────────────────────
const NEURO_GENRES = new Set([
  'classics','philosophy','theory','ancient','political theory','critical theory',
  'ancient history','greek','latin','continental philosophy','metaphysics',
  'epistemology','phenomenology','ethics','logic','aesthetics',
]);
const NEURO_AUTHORS = [
  'plato','aristotle','marx','hegel','kant','foucault','nietzsche','hume',
  'descartes','spinoza','leibniz','locke','rousseau','hobbes','wittgenstein',
  'heidegger','sartre','camus','derrida','althusser','lukács','gramsci',
  'socrates','thucydides','herodotus','homer','virgil','cicero','tacitus',
  'marcus aurelius','seneca','epictetus','augustine','aquinas','machiavelli',
  'confucius','laozi','zhuangzi','sun tzu','ibn khaldun','averroes',
];

function isNeuromancerStyle(book) {
  const genre = (book.genre||'').toLowerCase();
  const author = (book.author||'').toLowerCase();
  if (NEURO_GENRES.has(genre)) return true;
  if (NEURO_AUTHORS.some(a => author.includes(a))) return true;
  // Also check title keywords
  const title = (book.title||'').toLowerCase();
  const classicTitles = ['republic','iliad','odyssey','aeneid','capital','critique','phenomenology','being','ethics','meditations','symposium','apology','nicomachean','leviathan','discourse','genealogy','discipline'];
  if (classicTitles.some(t => title.includes(t))) return true;
  return false;
}

// ── 小花 / Bellflower SVG ─────────────────────────────────────────
// Grey-white tabby, loaf position, olive-green eyes, striped tail
// Woodcut illustration style — clean lines, Victorian book illustration feel
export function XiaoHuaSVG({ size = 60, style = {} }) {
  const w = size, h = size * 0.82;
  return (
    <svg width={w} height={h} viewBox="0 0 72 59" xmlns="http://www.w3.org/2000/svg" style={style}>
      {/* Body — loaf shape, grey back white front */}
      <ellipse cx="36" cy="38" rx="28" ry="16" fill="#c8c8c8" stroke="#5a5a5a" strokeWidth="1.2"/>
      {/* White chest/front */}
      <ellipse cx="36" cy="40" rx="18" ry="13" fill="#f0f0f0" stroke="#9a9a9a" strokeWidth="0.7"/>
      {/* Grey tabby stripes on back */}
      <path d="M14 33 Q20 30 26 33" fill="none" stroke="#8a8a8a" strokeWidth="1.2" strokeLinecap="round"/>
      <path d="M18 28 Q24 25 30 27" fill="none" stroke="#8a8a8a" strokeWidth="1.0" strokeLinecap="round"/>
      <path d="M46 27 Q52 25 57 29" fill="none" stroke="#8a8a8a" strokeWidth="1.0" strokeLinecap="round"/>
      <path d="M48 33 Q53 30 59 32" fill="none" stroke="#8a8a8a" strokeWidth="1.2" strokeLinecap="round"/>
      {/* Paws — white, tucked under */}
      <ellipse cx="26" cy="51" rx="6" ry="3.5" fill="#f0f0f0" stroke="#9a9a9a" strokeWidth="0.8"/>
      <ellipse cx="38" cy="53" rx="6.5" ry="3" fill="#f0f0f0" stroke="#9a9a9a" strokeWidth="0.8"/>
      <ellipse cx="50" cy="51" rx="6" ry="3.5" fill="#f0f0f0" stroke="#9a9a9a" strokeWidth="0.8"/>
      {/* Toe lines */}
      <line x1="23" y1="51" x2="23" y2="53.5" stroke="#b0b0b0" strokeWidth="0.6"/>
      <line x1="26" y1="52" x2="26" y2="54.5" stroke="#b0b0b0" strokeWidth="0.6"/>
      <line x1="29" y1="51" x2="29" y2="53.5" stroke="#b0b0b0" strokeWidth="0.6"/>
      {/* Striped tail curling around right side */}
      <path d="M62 40 Q70 46 65 52 Q60 57 52 55" fill="none" stroke="#7a7a7a" strokeWidth="2.8" strokeLinecap="round"/>
      <path d="M62 40 Q70 46 65 52 Q60 57 52 55" fill="none" stroke="#b8b8b8" strokeWidth="1.4" strokeLinecap="round" strokeDasharray="3 2"/>
      {/* Head */}
      <ellipse cx="36" cy="18" rx="14" ry="13" fill="#d0d0d0" stroke="#5a5a5a" strokeWidth="1.2"/>
      {/* White face */}
      <ellipse cx="36" cy="20" rx="10" ry="10" fill="#f2f2f2" stroke="#b0b0b0" strokeWidth="0.6"/>
      {/* Ears — grey with dark inner */}
      <polygon points="24,10 20,2 28,8" fill="#b8b8b8" stroke="#5a5a5a" strokeWidth="1"/>
      <polygon points="26,9 22,3 28,7" fill="#d8a0a0" stroke="none"/>
      <polygon points="48,10 52,2 44,8" fill="#b8b8b8" stroke="#5a5a5a" strokeWidth="1"/>
      <polygon points="46,9 50,3 44,7" fill="#d8a0a0" stroke="none"/>
      {/* Head tabby marks */}
      <path d="M29 10 Q31 8 33 10" fill="none" stroke="#8a8a8a" strokeWidth="0.9" strokeLinecap="round"/>
      <path d="M39 10 Q41 8 43 10" fill="none" stroke="#8a8a8a" strokeWidth="0.9" strokeLinecap="round"/>
      <path d="M30 14 Q33 12 36 13" fill="none" stroke="#9a9a9a" strokeWidth="0.7" strokeLinecap="round"/>
      {/* Eyes — olive green */}
      <ellipse cx="30" cy="18" rx="3.5" ry="2.8" fill="#7a8a3a" stroke="#3a4a18" strokeWidth="0.8"/>
      <ellipse cx="42" cy="18" rx="3.5" ry="2.8" fill="#7a8a3a" stroke="#3a4a18" strokeWidth="0.8"/>
      {/* Pupils */}
      <ellipse cx="30" cy="18" rx="1.4" ry="2.2" fill="#1a1a1a"/>
      <ellipse cx="42" cy="18" rx="1.4" ry="2.2" fill="#1a1a1a"/>
      {/* Eye shine */}
      <circle cx="31.2" cy="17" r="0.6" fill="white"/>
      <circle cx="43.2" cy="17" r="0.6" fill="white"/>
      {/* Nose */}
      <ellipse cx="36" cy="23" rx="2" ry="1.2" fill="#e0a0b0" stroke="#c08090" strokeWidth="0.5"/>
      {/* Mouth */}
      <path d="M34.5 24.5 Q36 26 37.5 24.5" fill="none" stroke="#9a7080" strokeWidth="0.7"/>
      {/* Whiskers */}
      <line x1="38" y1="22" x2="50" y2="20" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
      <line x1="38" y1="23" x2="51" y2="23" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
      <line x1="38" y1="24" x2="50" y2="26" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
      <line x1="34" y1="22" x2="22" y2="20" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
      <line x1="34" y1="23" x2="21" y2="23" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
      <line x1="34" y1="24" x2="22" y2="26" stroke="#a0a0a0" strokeWidth="0.6" opacity="0.8"/>
    </svg>
  );
}

// Tiny icon version — just the face, for inline notices
export function XiaoHuaIcon({ size = 20 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg">
      <ellipse cx="20" cy="22" rx="14" ry="13" fill="#d0d0d0" stroke="#5a5a5a" strokeWidth="1.2"/>
      <ellipse cx="20" cy="24" rx="10" ry="10" fill="#f2f2f2" stroke="#b0b0b0" strokeWidth="0.6"/>
      <polygon points="8,12 5,4 13,10" fill="#b8b8b8" stroke="#5a5a5a" strokeWidth="1"/>
      <polygon points="32,12 35,4 27,10" fill="#b8b8b8" stroke="#5a5a5a" strokeWidth="1"/>
      <ellipse cx="14" cy="21" rx="3.2" ry="2.5" fill="#7a8a3a" stroke="#3a4a18" strokeWidth="0.7"/>
      <ellipse cx="26" cy="21" rx="3.2" ry="2.5" fill="#7a8a3a" stroke="#3a4a18" strokeWidth="0.7"/>
      <ellipse cx="14" cy="21" rx="1.2" ry="2" fill="#1a1a1a"/>
      <ellipse cx="26" cy="21" rx="1.2" ry="2" fill="#1a1a1a"/>
      <circle cx="15" cy="20" r="0.5" fill="white"/>
      <circle cx="27" cy="20" r="0.5" fill="white"/>
      <ellipse cx="20" cy="27" rx="1.8" ry="1" fill="#e0a0b0"/>
      <line x1="22" y1="26" x2="31" y2="24" stroke="#b0b0b0" strokeWidth="0.6"/>
      <line x1="18" y1="26" x2="9" y2="24" stroke="#b0b0b0" strokeWidth="0.6"/>
    </svg>
  );
}

// ── NEUROMANCER COVER — classics & philosophy ─────────────────────
// Dark binding, circuit-trace border, glitch title typography
function NeuromancerCover({ book, width = 120, height = 160 }) {
  const rng     = seededRng(book.id + 'neo');
  const color   = book.color || '#2a6a2a';
  const bg      = toVeryDark(color);
  const accent  = lighten(color, 0.55);  // bright accent — the "green" of the cover
  const pct     = book.pages ? Math.min(100, Math.round((book.progress||0)/book.pages*100)) : 0;

  // Glitch offsets — seeded, consistent per book
  const glitch1Y = Math.round(rng() * 60 + 30);
  const glitch2Y = Math.round(rng() * 40 + 80);
  const glitch1W = Math.round(rng() * 40 + 20);
  const glitch2W = Math.round(rng() * 30 + 15);
  const glitch1X = Math.round(rng() * (width - glitch1W));
  const glitch2X = Math.round(rng() * (width - glitch2W));

  // Circuit corner — which corner is "broken"
  const brokenCorner = Math.floor(rng() * 4);

  return (
    <div style={{ width, height, background: bg, position: 'relative', overflow: 'hidden', borderRadius: '2px 3px 3px 2px' }}>
      {/* Circuit border — thin lines with nodes at corners */}
      <svg style={{ position:'absolute', inset:0, pointerEvents:'none' }} width={width} height={height} viewBox={`0 0 ${width} ${height}`} xmlns="http://www.w3.org/2000/svg">
        {/* Outer border lines */}
        <rect x="6" y="6" width={width-12} height={height-12} fill="none" stroke={accent} strokeWidth="0.6" opacity="0.5"/>
        <rect x="9" y="9" width={width-18} height={height-18} fill="none" stroke={accent} strokeWidth="0.35" opacity="0.3"/>

        {/* Corner circuit nodes — square pads */}
        {[[7,7],[width-7,7],[7,height-7],[width-7,height-7]].map(([cx,cy], i) => (
          i === brokenCorner
            ? <g key={i}>
                {/* Broken corner — partially missing */}
                <rect x={cx-4} y={cy-4} width={5} height={8} fill="none" stroke={accent} strokeWidth="0.7" opacity="0.3"/>
                <line x1={cx+2} y1={cy-4} x2={cx+2} y2={cy} stroke={accent} strokeWidth="2" opacity="0.6"/>
              </g>
            : <g key={i}>
                <rect x={cx-3} y={cy-3} width={6} height={6} fill={accent} opacity="0.55"/>
                <rect x={cx-5} y={cy-5} width={10} height={10} fill="none" stroke={accent} strokeWidth="0.5" opacity="0.35"/>
              </g>
        ))}

        {/* PCB traces along border — horizontal segments */}
        <line x1="16" y1="7" x2={width*0.4} y2="7" stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1={width*0.6} y1="7" x2={width-16} y2="7" stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1="16" y1={height-7} x2={width*0.35} y2={height-7} stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1={width*0.65} y1={height-7} x2={width-16} y2={height-7} stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        {/* Vertical segments */}
        <line x1="7" y1="16" x2="7" y2={height*0.38} stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1="7" y1={height*0.62} x2="7" y2={height-16} stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1={width-7} y1="16" x2={width-7} y2={height*0.42} stroke={accent} strokeWidth="0.8" opacity="0.4"/>
        <line x1={width-7} y1={height*0.58} x2={width-7} y2={height-16} stroke={accent} strokeWidth="0.8" opacity="0.4"/>

        {/* Small circuit node mid-borders */}
        <rect x={width*0.5-3} y="4" width="6" height="6" fill={accent} opacity="0.35"/>
        <rect x={width*0.5-3} y={height-10} width="6" height="6" fill={accent} opacity="0.35"/>

        {/* Glitch bars — horizontal corruption stripes */}
        <rect x={glitch1X} y={glitch1Y} width={glitch1W} height={2} fill={accent} opacity="0.18"/>
        <rect x={glitch2X} y={glitch2Y} width={glitch2W} height={1.5} fill={accent} opacity="0.14"/>
        {/* One pixel scatter */}
        <rect x={rng()*width|0} y={rng()*height|0} width="1" height="1" fill={accent} opacity="0.6"/>
        <rect x={rng()*width|0} y={rng()*height|0} width="2" height="1" fill={accent} opacity="0.4"/>
      </svg>

      {/* Title — Playfair italic, colour-outlined for PCB feel */}
      <div style={{ position:'absolute', top: 20, left: 10, right: 10 }}>
        <div style={{ fontSize: 12, fontWeight: 700, fontFamily: 'var(--font-display)', fontStyle: 'italic', color: accent, lineHeight: 1.2, letterSpacing: '0.04em', textShadow: `0 0 8px ${accent}66, 1px 1px 0 ${bg}` }}>
          {book.title}
        </div>
      </div>

      {/* Author — monospace, small, bottom */}
      <div style={{ position:'absolute', bottom: 22, left: 10, right: 10 }}>
        <div style={{ fontSize: 7.5, color: accent, opacity: 0.7, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.12em', textTransform: 'uppercase' }}>
          {book.author}
        </div>
        {book.year && <div style={{ fontSize: 6.5, color: accent, opacity: 0.4, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.08em', marginTop: 2 }}>
          {book.year < 0 ? `${Math.abs(book.year)} BCE` : book.year}
        </div>}
      </div>

      {/* Left spine shadow */}
      <div style={{ position:'absolute', left:0, top:0, bottom:0, width:5, background:'linear-gradient(to right, rgba(0,0,0,0.4), transparent)' }}/>

      {/* Progress line — glitchy green at bottom */}
      {book.status === 'reading' && pct > 0 && (
        <div style={{ position:'absolute', bottom:0, left:0, width:`${pct}%`, height:2, background:accent, opacity:0.8 }}/>
      )}
    </div>
  );
}

// ── LOEB COVER — history, literature, everything else ─────────────
// Solid binding, SVG border stamp (diamond-line repeat), central medallion
function LoebCover({ book, width = 120, height = 160 }) {
  const color   = book.color || '#7a5c38';
  const binding = darken(color, 0.28);
  const gold    = lighten(color, 0.62);
  const pct     = book.pages ? Math.min(100, Math.round((book.progress||0)/book.pages*100)) : 0;

  // Medallion glyph — based on book id hash
  const rng   = seededRng(book.id + 'loeb');
  const glyphs = ['✦', '◊', '⊕', '◈', '⊛', '✶', '◉', '⊗'];
  const medallion = glyphs[Math.floor(rng() * glyphs.length)];

  return (
    <div style={{ width, height, background: binding, position: 'relative', overflow: 'hidden', borderRadius: '2px 3px 3px 2px' }}>
      {/* SVG border stamp — diamond-dot-line repeat */}
      <svg style={{ position:'absolute', inset:0, pointerEvents:'none' }} width={width} height={height} viewBox={`0 0 ${width} ${height}`} xmlns="http://www.w3.org/2000/svg">
        {/* Outer double frame */}
        <rect x="5" y="5" width={width-10} height={height-10} fill="none" stroke={gold} strokeWidth="0.85" opacity="0.65"/>
        <rect x="8" y="8" width={width-16} height={height-16} fill="none" stroke={gold} strokeWidth="0.4" opacity="0.4"/>

        {/* Top border stamp — repeating diamond pattern */}
        {Array.from({length: Math.floor((width-24)/8)}, (_,i) => {
          const x = 14 + i * 8;
          const y = 6.5;
          return i % 2 === 0
            ? <polygon key={i} points={`${x},${y-2} ${x+2},${y} ${x},${y+2} ${x-2},${y}`} fill={gold} opacity="0.55"/>
            : <circle key={i} cx={x} cy={y} r="0.7" fill={gold} opacity="0.45"/>;
        })}
        {/* Bottom stamp */}
        {Array.from({length: Math.floor((width-24)/8)}, (_,i) => {
          const x = 14 + i * 8;
          const y = height - 6.5;
          return i % 2 === 0
            ? <polygon key={i} points={`${x},${y-2} ${x+2},${y} ${x},${y+2} ${x-2},${y}`} fill={gold} opacity="0.55"/>
            : <circle key={i} cx={x} cy={y} r="0.7" fill={gold} opacity="0.45"/>;
        })}
        {/* Left stamp */}
        {Array.from({length: Math.floor((height-24)/8)}, (_,i) => {
          const x = 6.5;
          const y = 14 + i * 8;
          return i % 2 === 0
            ? <polygon key={i} points={`${x-2},${y} ${x},${y-2} ${x+2},${y} ${x},${y+2}`} fill={gold} opacity="0.55"/>
            : <circle key={i} cx={x} cy={y} r="0.7" fill={gold} opacity="0.45"/>;
        })}
        {/* Right stamp */}
        {Array.from({length: Math.floor((height-24)/8)}, (_,i) => {
          const x = width - 6.5;
          const y = 14 + i * 8;
          return i % 2 === 0
            ? <polygon key={i} points={`${x-2},${y} ${x},${y-2} ${x+2},${y} ${x},${y+2}`} fill={gold} opacity="0.55"/>
            : <circle key={i} cx={x} cy={y} r="0.7" fill={gold} opacity="0.45"/>;
        })}

        {/* Corner ornaments */}
        {[[12,12],[width-12,12],[12,height-12],[width-12,height-12]].map(([cx,cy],i) => (
          <g key={i}>
            <polygon points={`${cx},${cy-5} ${cx+5},${cy} ${cx},${cy+5} ${cx-5},${cy}`} fill="none" stroke={gold} strokeWidth="0.8" opacity="0.6"/>
            <circle cx={cx} cy={cy} r="1.2" fill={gold} opacity="0.7"/>
          </g>
        ))}

        {/* Medallion circle */}
        <circle cx={width/2} cy={height/2} r="18" fill="none" stroke={gold} strokeWidth="0.8" opacity="0.45"/>
        <circle cx={width/2} cy={height/2} r="14" fill="none" stroke={gold} strokeWidth="0.4" opacity="0.3"/>
      </svg>

      {/* Medallion glyph */}
      <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-50%)', fontSize:22, color:gold, opacity:0.45, fontFamily:'var(--font-display)', lineHeight:1, userSelect:'none' }}>
        {medallion}
      </div>

      {/* Title — top section */}
      <div style={{ position:'absolute', top:16, left:13, right:13, textAlign:'center' }}>
        <div style={{ height:'0.5px', background:gold, opacity:0.35, marginBottom:6 }}/>
        <div style={{ fontSize:10, fontWeight:700, fontFamily:'var(--font-display)', fontStyle:'italic', color:gold, lineHeight:1.25, letterSpacing:'0.02em', textShadow:`0 1px 3px rgba(0,0,0,0.4)` }}>
          {book.title}
        </div>
        <div style={{ height:'0.5px', background:gold, opacity:0.35, marginTop:6 }}/>
      </div>

      {/* Author — bottom section */}
      <div style={{ position:'absolute', bottom:16, left:13, right:13, textAlign:'center' }}>
        <div style={{ height:'0.5px', background:gold, opacity:0.35, marginBottom:5 }}/>
        {book.author && <div style={{ fontSize:7.5, color:gold, opacity:0.75, fontStyle:'italic', lineHeight:1.2, fontFamily:'var(--font-serif)' }}>{book.author}</div>}
        {book.year && <div style={{ fontSize:6.5, color:gold, opacity:0.4, fontFamily:'var(--font-mono)', fontStyle:'normal', letterSpacing:'0.08em', marginTop:2 }}>
          {book.year < 0 ? `${Math.abs(book.year)} BCE` : book.year}
        </div>}
      </div>

      {/* Left spine shadow */}
      <div style={{ position:'absolute', left:0, top:0, bottom:0, width:5, background:'linear-gradient(to right, rgba(0,0,0,0.25), transparent)' }}/>

      {/* Progress */}
      {book.status === 'reading' && pct > 0 && (
        <div style={{ position:'absolute', bottom:0, left:0, width:`${pct}%`, height:2, background:gold, opacity:0.6 }}/>
      )}
    </div>
  );
}

// ── PUBLIC: BookCard ──────────────────────────────────────────────
export function BookCard({ book, status, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const isNeo = isNeuromancerStyle(book);
  const color  = book.color || '#7a5c38';
  const accent = isNeo ? lighten(color, 0.55) : lighten(color, 0.62);
  const pct    = book.pages ? Math.min(100,Math.round((book.progress||0)/book.pages*100)) : 0;

  return (
    <div onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ width:120, flexShrink:0, cursor:'pointer', position:'relative',
        transform: hovered ? 'translateY(-7px) rotate(-0.5deg)' : 'translateY(0)',
        transition:'transform 0.2s cubic-bezier(.2,.8,.3,1)',
        filter: selected ? `drop-shadow(0 0 6px ${color}88)` : 'none',
      }}>
      <div style={{ borderRadius:'2px 3px 3px 2px',
        boxShadow: hovered
          ? `3px 8px 22px rgba(0,0,0,0.35), -1px 0 0 rgba(0,0,0,0.18), inset -3px 0 6px rgba(0,0,0,0.12)`
          : `2px 4px 12px rgba(0,0,0,0.22), -1px 0 0 rgba(0,0,0,0.14), inset -2px 0 4px rgba(0,0,0,0.08)`,
        transition:'box-shadow 0.2s',
        overflow:'hidden',
      }}>
        {isNeo
          ? <NeuromancerCover book={book} width={120} height={160}/>
          : <LoebCover book={book} width={120} height={160}/>
        }
        {status && (
          <div style={{ background: isNeo ? 'rgba(0,0,0,0.7)' : darken(color,0.45), padding:'3px 8px', fontSize:7, color:accent, opacity:0.85, fontFamily:'var(--font-mono)', fontStyle:'normal', letterSpacing:'0.07em', textAlign:'center' }}>
            {status.label.toUpperCase()}
          </div>
        )}
      </div>
    </div>
  );
}

// ── PUBLIC: BookSpine ─────────────────────────────────────────────
export function BookSpine({ book, height = 120, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const isNeo   = isNeuromancerStyle(book);
  const color   = book.color || '#7a5c38';
  const binding = isNeo ? toVeryDark(color) : darken(color, 0.28);
  const accent  = isNeo ? lighten(color, 0.55) : lighten(color, 0.62);
  const w = Math.max(18, Math.min(32, Math.floor(((book.pages||300)/800)*36)+12));

  return (
    <div onClick={onClick}
      title={`${book.title}${book.author?' — '+book.author:''}`}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ width:w, height, flexShrink:0, cursor:'pointer',
        transform: hovered ? 'translateY(-6px)' : 'none',
        transition:'transform 0.18s cubic-bezier(.2,.8,.3,1)',
      }}>
      <div style={{ width:'100%', height:'100%', background:binding,
        borderRadius:'2px 3px 3px 2px', overflow:'hidden', position:'relative',
        boxShadow: selected ? `0 0 0 2px ${color}, 2px 3px 10px rgba(0,0,0,0.3)`
          : hovered ? '2px 5px 14px rgba(0,0,0,0.3)' : '1px 2px 6px rgba(0,0,0,0.2)',
        transition:'box-shadow 0.18s',
      }}>
        {/* Top accent stripe */}
        <div style={{ height:8, background:isNeo?'transparent':darken(color,0.15), borderBottom:`1px solid ${accent}55` }}/>
        {/* Rotated title */}
        <div style={{ position:'absolute', top:12, bottom:12, left:0, right:0, display:'flex', alignItems:'center', justifyContent:'center' }}>
          <div style={{ writingMode:'vertical-rl', textOrientation:'mixed', transform:'rotate(180deg)',
            fontSize:8.5, fontWeight:isNeo?700:600, color:accent, letterSpacing:isNeo?'0.06em':'0.04em',
            padding:'4px 2px', overflow:'hidden', maxHeight:height-28,
            textOverflow:'ellipsis', whiteSpace:'nowrap', lineHeight:1.2,
            fontFamily: isNeo ? 'var(--font-mono)' : 'var(--font-display)',
            fontStyle: isNeo ? 'normal' : 'italic',
            textShadow: isNeo ? `0 0 6px ${accent}66` : `0 1px 2px rgba(0,0,0,0.35)`,
          }}>{book.title}</div>
        </div>
        {/* Bottom rule */}
        <div style={{ position:'absolute', bottom:8, left:2, right:2, height:'0.75px', background:accent, opacity:0.5 }}/>
        {/* Left edge */}
        <div style={{ position:'absolute', left:0, top:0, bottom:0, width:3, background:'linear-gradient(to right, rgba(0,0,0,0.25), transparent)' }}/>
      </div>
    </div>
  );
}
